// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *SalesShipmentHeader) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, SalesShipmentHeaderTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$Sales_Shipment_Header$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (sell_to_customer_no)`,
		fmt.Sprintf("%s$Sales_Shipment_Header$customer", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index customer: %w", err)
	}
	var keys []sift.Key
	for _, spec := range salesShipmentHeaderSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, SalesShipmentHeaderTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, SalesShipmentHeaderTableName, keys)
}

// salesShipmentHeaderSIFTSpecs are the table's keys with sum_index_fields
func salesShipmentHeaderSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *SalesShipmentHeader) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, SalesShipmentHeaderTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range salesShipmentHeaderSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, SalesShipmentHeaderTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: SalesShipmentHeaderTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, SalesShipmentHeaderTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

